// scripts/copy-pdf-worker.js
const fs = require('fs');
const path = require('path');

const src = path.resolve(__dirname, '..', 'node_modules', 'pdfjs-dist', 'build', 'pdf.worker.min.js');
const destDir = path.resolve(__dirname, '..', 'src', 'assets', 'pdfjs');
const dest = path.join(destDir, 'pdf.worker.min.js');

try {
  if (!fs.existsSync(src)) {
    console.warn('[copy-pdf-worker] Source worker not found at:', src);
    process.exit(0); // don't fail install if it's missing
  }
  fs.mkdirSync(destDir, { recursive: true });
  fs.copyFileSync(src, dest);
  console.log('[copy-pdf-worker] Copied pdf.worker.min.js to', dest);
} catch (err) {
  console.error('[copy-pdf-worker] Failed to copy pdf.worker.min.js:', err);
  // do not error out the whole install — log and continue
}
